using System;
using MessagePack;
using MessagePack.Resolvers;
using Xunit;

public class Probe2283UntrustedDataDepthTests
{
    [Fact]
    public void UntrustedDataRejectsDeeplyNestedInput()
    {
        byte[] payload = BuildNested(1000);
        var options = MessagePackSerializerOptions.Standard
            .WithResolver(StandardResolver.Instance)
            .WithSecurity(MessagePackSecurity.UntrustedData);
        Assert.ThrowsAny<Exception>(() => MessagePackSerializer.Deserialize<object>(payload, options));
    }

    private static byte[] BuildNested(int depth)
    {
        byte[] bytes = new byte[depth + 1];
        for (int i = 0; i < depth; i++)
        {
            bytes[i] = 0x91; // array of 1 element
        }

        bytes[depth] = 0xc0; // nil leaf
        return bytes;
    }
}

using System;
using System.Collections.Immutable;
using System.IO;
using System.Linq;
using System.Threading;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Diagnostics;
using Microsoft.CodeAnalysis.Testing;
using Xunit;

public class Probe2283MetadataUnkeyedTests
{
    [Fact]
    public async Task UnkeyedMemberOfMetadataStructIsReportedToConsumer()
    {
        string defineSource = @"
using MessagePack;
namespace Lib
{
    [MessagePackObject]
    public struct Item<T>
    {
        [Key(0)] public string Key { get; set; }
        public int Unkeyed { get; set; }
    }
}";
        string usageSource = @"
using MessagePack;
using Lib;

[MessagePackObject]
public class Consumer
{
    [Key(0)]
    public Item<int> Value { get; set; }
}
";

        ImmutableArray<MetadataReference> framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        var references = framework.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)).ToList();

        var defineParseOptions = CSharpParseOptions.Default.WithLanguageVersion(LanguageVersion.Latest);
        var defineCompilation = CSharpCompilation.Create(
            "Lib",
            new[] { CSharpSyntaxTree.ParseText(defineSource, defineParseOptions) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        using var stream = new MemoryStream();
        var emit = defineCompilation.Emit(stream);
        Assert.True(emit.Success, string.Join(Environment.NewLine, emit.Diagnostics));
        var definingRef = MetadataReference.CreateFromImage(stream.ToArray());

        // Build the usage compilation referencing the metadata-only assembly, with no analyzers from the defining assembly present.
        var usageParseOptions = CSharpParseOptions.Default.WithLanguageVersion(LanguageVersion.Latest);
        var usageCompilation = CSharpCompilation.Create(
            "Consumer",
            new[] { CSharpSyntaxTree.ParseText(usageSource, usageParseOptions) },
            framework.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)).Append(definingRef),
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        var analyzer = new MessagePack.SourceGenerator.Analyzers.MsgPack00xMessagePackAnalyzer();
        var diagnostics = (await usageCompilation
            .WithAnalyzers(ImmutableArray.Create<DiagnosticAnalyzer>(analyzer))
            .GetAnalyzerDiagnosticsAsync())
            .Where(d => d.Id == "MsgPack004")
            .ToList();

        // A referenced binary built without these analyzers has no chance to report; the consumer must still report it.
        Assert.True(diagnostics.Count > 0, "Expected a MsgPack004 diagnostic for the unkeyed member of the referenced struct, but the consumer compilation reported none.");
    }
}
